      nuGetSourcesConfigPath: solutionOptions.nuGetSourcesConfigPath,
      feedFolder: solutionOptions.feedFolder,
      logLevel: solutionOptions.logLevel,
      skipAnalyze: solutionOptions.validateOptions.skipAnalyze,
